import {
  afterAll,
  beforeAll,
  beforeEach,
  describe,
  expect,
  it,
  vi,
} from "vitest";
import {
  boundary,
  usageFixture,
  usageOwner,
  setGating,
} from "./fixtures/usage-worker";
import { databaseTestsEnabled } from "./helpers/foundation-db";
import { createCampaign } from "@/lib/campaigns";
import { deliverOne } from "@/lib/inngest";
import { dispatchUsagePending } from "@/lib/usage-reconciliation";
import { applyFreeCampaignPolicy } from "@/lib/campaign-policy";
import {
  claimUsage,
  importUsageEvidence,
  withUsageTransaction,
} from "@/lib/usage-ledger";
import { resolveUsagePeriods } from "@/lib/usage-periods";
import { dismissAccountNotice } from "@/lib/account-notices";
import { readQuotaSnapshot } from "@/lib/quota-usage";

describe.runIf(databaseTestsEnabled)(
  "whole-campaign downgrade allocation",
  () => {
    let fixture: Awaited<ReturnType<typeof usageFixture>>;
    const now = new Date("2026-10-20T12:00:00Z");
    beforeAll(async () => {
      fixture = await usageFixture();
    });
    beforeEach(async () => {
      vi.useFakeTimers({ toFake: ["Date"] });
      vi.setSystemTime(now);
      await setGating(boundary.db, true);
    });
    afterAll(async () => {
      vi.useRealTimers();
      if (fixture) await fixture.close();
    });
    const sweep = (id: string) =>
      withUsageTransaction(boundary.db, id, (owner) =>
        applyFreeCampaignPolicy(owner, now),
      );
    async function downgrade(id: string) {
      await boundary.db.user.update({
        where: { id },
        data: { cancelAtPeriodEnd: true, currentPeriodEnd: now },
      });
    }
    async function status(id: string, campaignId: string) {
      return boundary.db.send.findMany({
        where: { campaignId, campaign: { userId: id } },
        orderBy: { id: "asc" },
      });
    }
    it("allocates exact fits oldest first, cancels complete later remainders and never revives them", async () => {
      const f = await usageOwner(boundary.db, { paid: true });
      const first = await createCampaign(f.user.id, await f.input(2));
      vi.setSystemTime(new Date(+now + 1));
      const second = await createCampaign(f.user.id, await f.input(2));
      vi.setSystemTime(new Date(+now + 2));
      const third = await createCampaign(f.user.id, await f.input(1));
      vi.setSystemTime(now);
      await boundary.db.send.updateMany({
        where: { campaignId: first.id, campaign: { userId: f.user.id } },
        data: { availableAt: new Date(+now + 3600000) },
      });
      await downgrade(f.user.id);
      await sweep(f.user.id);
      expect(
        (await status(f.user.id, first.id)).every((s) => s.status === "QUEUED"),
      ).toBe(true);
      expect(
        (await status(f.user.id, second.id)).every(
          (s) => s.status === "CANCELLED",
        ),
      ).toBe(true);
      expect((await status(f.user.id, third.id))[0].status).toBe("QUEUED");
      await sweep(f.user.id);
      expect(
        await boundary.db.accountNotice.count({ where: { userId: f.user.id } }),
      ).toBe(1);
      const snapshot = await readQuotaSnapshot(f.user.id);
      expect(snapshot.mode === "gated" && snapshot.daily.remaining).toBe(0);
      await boundary.db.user.update({
        where: { id: f.user.id },
        data: {
          cancelAtPeriodEnd: false,
          currentPeriodEnd: new Date(+now + 86400000),
        },
      });
      await sweep(f.user.id);
      expect(
        (await status(f.user.id, second.id)).every(
          (s) => s.status === "CANCELLED",
        ),
      ).toBe(true);
      const notice = await boundary.db.accountNotice.findFirstOrThrow({
        where: { userId: f.user.id },
      });
      const other = await usageOwner(boundary.db);
      await dismissAccountNotice(other.user.id, notice.id);
      expect(
        (
          await boundary.db.accountNotice.findUniqueOrThrow({
            where: { id: notice.id },
          })
        ).dismissedAt,
      ).toBeNull();
      await dismissAccountNotice(f.user.id, notice.id);
      expect(
        (
          await boundary.db.accountNotice.findUniqueOrThrow({
            where: { id: notice.id },
          })
        ).dismissedAt,
      ).not.toBeNull();
    });
    it("counts imported Paid consumption in the same Free month and keeps uncertain claims", async () => {
      const f = await usageOwner(boundary.db, { paid: true });
      const campaign = await createCampaign(f.user.id, await f.input(3));
      const sends = await status(f.user.id, campaign.id);
      await withUsageTransaction(boundary.db, f.user.id, async (owner) => {
        await claimUsage(
          owner,
          sends[0].id,
          resolveUsagePeriods(f.user, now),
          true,
          now,
        );
        for (let i = 0; i < 14; i++)
          await importUsageEvidence(owner, {
            sourceKey: `paid-${i}`,
            deliveryKey: null,
            chargedAt: new Date(+now - 86400000),
            timestampSource: "sentAt",
          });
      });
      await downgrade(f.user.id);
      await sweep(f.user.id);
      expect(
        (await status(f.user.id, campaign.id)).filter(
          (s) => s.status === "CANCELLED",
        ),
      ).toHaveLength(2);
      expect(
        (await status(f.user.id, campaign.id)).find((s) => s.id === sends[0].id)
          ?.deliveryState,
      ).toBe("ATTEMPTING");
      const snapshot = await readQuotaSnapshot(f.user.id);
      expect(snapshot.mode === "gated" && snapshot.monthly.remaining).toBe(0);
    });
    it.each(["size", "role", "template"])(
      "uses original approval evidence for %s after downgrade",
      async (feature) => {
        const f = await usageOwner(boundary.db, { paid: true });
        const input = await f.input(feature === "size" ? 4 : 2);
        if (feature === "role")
          Object.assign(input, {
            recipientRoles: { [input.recipientIds[0]]: "Research Wizard" },
          });
        const campaign = await createCampaign(f.user.id, input);
        if (feature === "size") {
          // Simulate removed history/contact while retaining original approval count.
          const rows = await status(f.user.id, campaign.id);
          await boundary.db.send.delete({
            where: { id: rows[0].id, campaign: { userId: f.user.id } },
          });
        }
        if (feature === "template") {
          const selected = await boundary.db.template.create({
            data: {
              userId: f.user.id,
              name: "Free",
              subject: "Hello",
              body: "Hello",
            },
          });
          await boundary.db.user.update({
            where: { id: f.user.id },
            data: { freeTemplateId: selected.id },
          });
        }
        await downgrade(f.user.id);
        await sweep(f.user.id);
        expect(
          (await status(f.user.id, campaign.id)).every(
            (s) => s.status === "CANCELLED",
          ),
        ).toBe(feature !== "role");
      },
    );
    it("rechecks the exact downgrade deadline after Gmail preparation and before claiming", async () => {
      const f = await usageOwner(boundary.db, { paid: true });
      const campaign = await createCampaign(f.user.id, await f.input(4));
      const expires = new Date(+now + 1000);
      await boundary.db.user.update({
        where: { id: f.user.id },
        data: { currentPeriodEnd: expires, cancelAtPeriodEnd: true },
      });
      boundary.send.mockClear();
      boundary.gmail.mockImplementationOnce(async () => {
        vi.setSystemTime(expires);
        return {
          email: "[REDACTED_EMAIL]",
          gmail: { users: { messages: { send: boundary.send } } },
        };
      });
      const send = (await status(f.user.id, campaign.id))[0];
      expect((await deliverOne(f.user.id, send.id)).outcome).toBe("done");
      expect(boundary.send).not.toHaveBeenCalled();
      expect(
        (await status(f.user.id, campaign.id)).every(
          (row) => row.status === "CANCELLED",
        ),
      ).toBe(true);
    });
    it("does not cancel work at an unresolved ordinary renewal or during a Paid grant", async () => {
      const f = await usageOwner(boundary.db, { paid: true });
      const campaign = await createCampaign(f.user.id, await f.input(4));
      await boundary.db.user.update({
        where: { id: f.user.id },
        data: { currentPeriodEnd: now },
      });
      await sweep(f.user.id);
      const publish = vi.fn();
      expect(await dispatchUsagePending(f.user.id, publish, now)).toBe(0);
      const send = (await status(f.user.id, campaign.id))[0];
      expect((await deliverOne(f.user.id, send.id)).outcome).toBe("deferred");
      expect(
        (await status(f.user.id, campaign.id)).every(
          (s) => s.status === "QUEUED",
        ),
      ).toBe(true);
      await boundary.db.user.update({
        where: { id: f.user.id },
        data: {
          cancelAtPeriodEnd: true,
          grandfatheredUntil: new Date(+now + 60000),
        },
      });
      await sweep(f.user.id);
      expect(
        (await status(f.user.id, campaign.id)).every(
          (s) => s.status === "QUEUED",
        ),
      ).toBe(true);
    });
  },
);
